'use strict';
const field=id=>document.getElementById('booking-'+id), form=document.getElementById('booking-form');
const format=n=>new Intl.NumberFormat('en-JM',{style:'currency',currency:'JMD',currencyDisplay:'code'}).format(n);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Jamaica',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
field('pickup').min=today();field('return').min=today();
const params=new URLSearchParams(location.search);if(['fit','shuttle'].includes(params.get('car')))field('car').value=params.get('car');
for(const key of ['pickup','return'])if(/^\d{4}-\d{2}-\d{2}$/.test(params.get(key)||''))field(key).value=params.get(key);
function estimate(){if(!field('pickup').value||!field('return').value)throw new Error('Choose your pick-up and return dates.');if(field('pickup').value<today())throw new Error('Pick-up must be today or later.');return calculateRental({car:field('car').value,pickup:field('pickup').value,returnDate:field('return').value,currency:'JMD'},RENTAL_CONFIG);}
function render(){for(const id of ['days','total','deposit','balance'])field(id).textContent='—';field('error').textContent='';try{const r=estimate();if(r.status!=='ready')throw new Error('Please call us for pricing.');field('days').textContent=r.days+' '+(r.days===1?'day':'days');for(const id of ['total','deposit','balance'])field(id).textContent=format(r[id]);field('status').textContent='Estimated rental cost in JMD. Availability and final price are confirmed by our team.';}catch(e){field('status').textContent=e.message;}}
for(const id of ['car','pickup','return'])field(id).addEventListener('change',render);
form.addEventListener('submit',e=>{e.preventDefault();try{const r=estimate();if(r.status!=='ready')throw new Error('Please call us for pricing.');const name=field('name').value.trim(),phone=field('phone').value.trim();if(!name)throw new Error('Please enter your name.');if(!/^[+\d\s().-]+$/.test(phone)||phone.replace(/\D/g,'').length<7)throw new Error('Please enter a valid phone number including country code.');const car=field('car').value==='fit'?'2017 Honda Fit':'2018 Honda Fit Shuttle';const message=['Hello Grant Premium Rental, I would like to request a booking.','', 'Name: '+name,'Phone: '+phone,'Car: '+car,'Pick-up: '+field('pickup').value,'Return: '+field('return').value,'Duration: '+r.days+' day(s)','Estimated rental: '+format(r.total),'50% deposit: '+format(r.deposit),'Remaining balance: '+format(r.balance),field('notes').value.trim()?'Notes: '+field('notes').value.trim():'','Please confirm availability, the final price, and payment instructions.'].filter(Boolean).join('\n');location.assign('https://wa.me/18763849602?text='+encodeURIComponent(message));}catch(err){field('error').textContent=err.message;}});render();
